if (window.top && window.top.VirtualCursor) {
    window.top.VirtualCursor.attach(window);
}

(function () {
    const store = window.top.SiteCore.createStore();

    if (store.online_flag === "1") {
        document.getElementById('control-panel').classList.add("hidden")
    } else {
        const zhText = document.getElementById('zhText');
        const engText = document.getElementById('engText');
        const toggleBtn = document.getElementById('toggleBtn');
        const saveBtn = document.getElementById('saveBtn');
        const statusBar = document.getElementById('status-bar');
        const lockScreen = document.getElementById('lock-screen');
        const lockMsg = document.getElementById('lock-msg');

        const DOC_KEY = document.title.trim();
        let insertMode = false;

        const DB_NAME = "AlignDrafts";
        const STORE_NAME = "draft_texts";

        let _db = null;
        let _dbPromise = null;
        function initDB() {
            if (_db) return Promise.resolve(_db);
            if (_dbPromise) return _dbPromise;
            _dbPromise = new Promise((resolve, reject) => {
                const req = indexedDB.open(DB_NAME, 1);
                req.onupgradeneeded = e => {
                    if (!e.target.result.objectStoreNames.contains(STORE_NAME)) {
                        e.target.result.createObjectStore(STORE_NAME);
                    }
                };
                req.onsuccess = e => {
                    const db = e.target.result;
                    _db = db;
                    _dbPromise = null;
                    db.onversionchange = () => { db.close(); if (_db === db) _db = null; };
                    db.onclose = () => { if (_db === db) _db = null; };
                    resolve(db);
                };
                req.onerror = e => {
                    _dbPromise = null;
                    reject(e);
                };
            });
            return _dbPromise;
        }
        window.addEventListener('pagehide', () => {
            if (_db) { try { _db.close(); } catch (_) { } _db = null; }
        });

        async function saveDraft(text) {
            const db = await initDB();
            return new Promise(resolve => {
                const tx = db.transaction(STORE_NAME, "readwrite");
                tx.objectStore(STORE_NAME).put(text, DOC_KEY);
                tx.oncomplete = () => {
                    const now = new Date();
                    statusBar.textContent = `已自动暂存 ${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`;
                    resolve();
                };
            });
        }

        async function loadDraft() {
            const db = await initDB();
            return new Promise(resolve => {
                const tx = db.transaction(STORE_NAME, "readonly");
                const req = tx.objectStore(STORE_NAME).get(DOC_KEY);
                req.onsuccess = () => resolve(req.result);
                req.onerror = () => resolve(null);
            });
        }

        async function destroyDraft() {
            const db = await initDB();
            return new Promise(resolve => {
                const tx = db.transaction(STORE_NAME, "readwrite");
                tx.objectStore(STORE_NAME).delete(DOC_KEY);
                tx.oncomplete = () => resolve();
            });
        }

        let debounceTimer;
        function triggerAutoSave() {
            clearTimeout(debounceTimer);
            statusBar.textContent = "检测到输入，等待保存...";
            debounceTimer = setTimeout(() => {
                saveDraft(zhText.innerText);
            }, 2000);
        }

        function syncHeight() {
            zhText.style.height = "auto";
            const targetHeight = Math.max(engText.clientHeight, zhText.scrollHeight);
            engText.style.height = targetHeight + "px";
            zhText.style.height = targetHeight + "px";
        }

        toggleBtn.addEventListener('click', () => {
            insertMode = !insertMode;
            toggleBtn.textContent = "快速换行: " + (insertMode ? "开" : "关");

            if (insertMode) {
                toggleBtn.style.background = "#e74c3c";
                toggleBtn.style.color = "white";
                toggleBtn.style.borderColor = "#e74c3c";
            } else {
                toggleBtn.style.background = "";
                toggleBtn.style.color = "";
                toggleBtn.style.borderColor = "";
            }
        });

        zhText.addEventListener('input', () => {
            syncHeight();
            triggerAutoSave();
        });

        window.addEventListener('resize', syncHeight);

        zhText.addEventListener('click', () => {
            if (!insertMode) return;
            const sel = window.getSelection();
            if (sel.rangeCount > 0 && sel.isCollapsed && zhText.contains(sel.anchorNode)) {
                insertAtCursor(zhText, "\n  ");
                syncHeight();
                triggerAutoSave();
            }
        });

        function insertAtCursor(field, text) {
            const sel = window.getSelection();
            if (!sel.rangeCount) return;
            const range = sel.getRangeAt(0);
            
            const textNode = document.createTextNode(text);
            range.insertNode(textNode);
            
            range.setStartAfter(textNode);
            range.setEndAfter(textNode);
            sel.removeAllRanges();
            sel.addRange(range);
        }

        async function bootstrap() {
            try {
                const draftText = await loadDraft();
                if (draftText !== undefined && draftText !== null && draftText !== zhText.innerText) {
                    lockMsg.textContent = "发现本地草稿，正在回填反序列化...";
                    await new Promise(r => setTimeout(r, 200));
                    if (Object.getOwnPropertyDescriptor(zhText, "value")?.set) {
                        zhText.value = draftText;
                    } else {
                        zhText.innerText = draftText;
                    }
                    statusBar.textContent = "已恢复上次草稿";
                } else {
                    statusBar.textContent = "就绪 (暂无草稿)";
                }
            } catch (e) {
                console.error("IDB 读取失败", e);
            } finally {
                syncHeight();
                lockScreen.style.display = "none";
            }
        }

        bootstrap();

        saveBtn.addEventListener('click', async () => {
            clearTimeout(debounceTimer);

            const htmlClone = document.documentElement.cloneNode(true);

            const clonedZhText = htmlClone.querySelector('#zhText');
            clonedZhText.textContent = zhText.innerText;

            htmlClone.querySelector('#engText').style.height = '';
            clonedZhText.style.height = '';
            
            const clonedToggleBtn = htmlClone.querySelector('#toggleBtn');
            if (clonedToggleBtn) {
                clonedToggleBtn.textContent = "快速换行: 关";
                clonedToggleBtn.style.background = "";
                clonedToggleBtn.style.color = "";
                clonedToggleBtn.style.borderColor = "";
            }

            const garbageSelectors = [
                '#bar',
                '#gotop',
                '.pinyin-tooltip',
                '#giscus-popup',
                'link[href*="content.css"]',
                '#toc',
                '#excerpt-pop-btn',
                '#search-minimap',
                '#diff-minimap',
                '#diff-controls-wrapper',
                '#search-hl-static',
                '#content-init-fade',
                '.active-search-border',
                '.lightbox',
                '.code-tools',
                '.code-line-highlighter',
                '#diff-pre',
                'link[href*="prism.css"]',
                'script[src*="prism.js"]'
            ];
            garbageSelectors.forEach(selector => {
                htmlClone.querySelectorAll(selector).forEach(el => el.remove());
            });
            htmlClone.querySelectorAll('style').forEach(st => {
                if (st.textContent && st.textContent.trim() === 'body { opacity: 0; transition: opacity 0.3s ease; }') {
                    st.remove();
                }
            });
            const clonedBody = htmlClone.querySelector('body');
            if (clonedBody) {
                clonedBody.style.removeProperty('opacity');
                clonedBody.style.removeProperty('transition');
                if (!clonedBody.getAttribute('style')?.trim()) {
                    clonedBody.removeAttribute('style');
                }
            }

            const htmlString = "<!DOCTYPE html>\n" + htmlClone.outerHTML;
            const textarea = document.createElement('textarea');
            textarea.value = htmlString;
            textarea.style.position = 'fixed';
            textarea.style.opacity = '0';
            document.body.appendChild(textarea);
            textarea.focus();
            textarea.select();
            textarea.setSelectionRange(0, htmlString.length);
            let copied = false;
            try { copied = document.execCommand('copy'); } catch (e) { }
            document.body.removeChild(textarea);

            if (!copied) {
                alert("❌ 写入剪贴板失败，为防止源文档被覆盖已中止固化！");
                return;
            }

            const safeTitle = document.title.trim() || "Unknown";

            let baselineHtml = "";
            try {
                const res = await fetch(location.href, { cache: 'no-store' });
                if (res.ok) baselineHtml = await res.text();
            } catch (_) { }

            // 先生成认证加密信封，失败则中止（保护本地草稿不被销毁、不进入锁屏）
            let protocolUrl = "";
            try {
                if (window.top && typeof window.top.sealProtocolUrl === "function") {
                    protocolUrl = await window.top.sealProtocolUrl(5, safeTitle);
                } else {
                    const m = await import("/src/js/shared-utils.js");
                    protocolUrl = await m.sealProtocolUrl(5, safeTitle);
                }
            } catch (err) {
                alert("❌ 本地协议封包失败，已保留草稿并中止固化：" + (err && err.message ? err.message : String(err)));
                return;
            }

            try { await destroyDraft(); } catch (_) { }

            lockScreen.style.display = "flex";
            lockScreen.style.flexDirection = "column";
            lockScreen.style.gap = "12px";
            lockScreen.innerHTML = `<div id="bil-lock-text">⌛固化中..</div>`;

            window.location.href = protocolUrl;

            const normText = (s) => (s || '').replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n');
            const expectedHtml = normText(htmlString);
            const baseNorm = normText(baselineHtml);

            let pollCount = 0;
            let unlocked = false;
            const unlockTimer = setTimeout(() => {
                if (unlocked) return;
                const btn = document.createElement('button');
                btn.textContent = '解除锁定 / 刷新检查';
                btn.style.cssText = 'padding:6px 14px;cursor:pointer;font-size:13px;';
                btn.onclick = () => {
                    unlocked = true;
                    clearInterval(pollTimer);
                    lockScreen.style.display = "none";
                };
                lockScreen.appendChild(btn);
            }, 6000);

            const pollTimer = setInterval(async () => {
                if (unlocked) { clearInterval(pollTimer); return; }
                pollCount++;
                if (pollCount > 45) {
                    clearInterval(pollTimer);
                    const lbl = document.getElementById('bil-lock-text');
                    if (lbl) lbl.textContent = '⚠️ 等待固化超时，请确认外部终端完成后手动刷新';
                    return;
                }
                try {
                    const r = await fetch(location.href + (location.search ? '&' : '?') + '_t=' + Date.now(), { cache: 'no-store' });
                    if (r.ok) {
                        const latestNorm = normText(await r.text());
                        if ((baseNorm && latestNorm && latestNorm !== baseNorm) || (expectedHtml && latestNorm === expectedHtml)) {
                            unlocked = true;
                            clearTimeout(unlockTimer);
                            clearInterval(pollTimer);
                            location.reload();
                        }
                    }
                } catch (_) { }
            }, 400);
        });
    }
})();